// All the game's sound, made with the browser's Web Audio API
//every note and effect is generated by code
//
// There are TWO music tracks:
//   menu - a soft, shimmering harp-like melody for the home / menu screens
//   game - a slow, moody pad that plays during a game
// Browsers block sound until the player clicks something, so unlock() is called from clicks

// The key used to remember the volume settings in the browser (localStorage)
const KEY = 'gdb.audio'

export class AudioService {
  constructor() {
    // Load previously saved volumes, if any
    let saved = null
    try { saved = JSON.parse(localStorage.getItem(KEY)) } catch { /* ignore a corrupt value */ }
    this.music = saved?.music ?? 0.25  // music volume, 0 (off) to 1 (full)
    this.sfx = saved?.sfx ?? 0.7       // sound effect volume
    this.ctx = null                    // the audio engine (created on the first click)
    this.timer = null                  // repeating timer that plays the next bar of music
    this.track = 'menu'                // which track should be playing
    this.bar = 0                       // which chord of the track comes next
  }

  // Starts the audio engine (must be called from a user click)
  unlock() {
    if (!this.ctx) {
      // Safari uses an older name for AudioContext
      const AC = window.AudioContext || window.webkitAudioContext
      if (!AC) return
      this.ctx = new AC()
      // Two volume knobs: one for music, one for sound effects
      this.musicGain = this.ctx.createGain()
      this.sfxGain = this.ctx.createGain()
      // Connect both to the speakers.
      this.musicGain.connect(this.ctx.destination)
      this.sfxGain.connect(this.ctx.destination)
    }
    // Browsers may start the engine "suspended"; wake it up
    if (this.ctx.state === 'suspended') this.ctx.resume()
    this.#apply()
  }

  // Changes the music volume (0 to 1) and remembers it
  setMusic(v) { this.music = v; this.#save(); this.#apply() }
  // Changes the sound-effect volume (0 to 1) and remembers it.
  setSfx(v) { this.sfx = v; this.#save(); this.#apply() }

  // Switches between the 'menu' and 'game' music
  setTrack(name) {
    // Nothing to do if that track is already selected.
    if (name === this.track) return
    this.track = name
    this.bar = 0
    // Stop the old track's timer so the new track starts cleanly.
    clearInterval(this.timer)
    this.timer = null
    this.#apply()
  }

  // ---------------------------------------------------------- sound effects -------------------------------------------------

  // A tiny click for buttons
  click() { this.#tone(660, { dur: 0.05, type: 'square', gain: 0.08 }) }

  // A rattle: seven short bursts of noise
  dice() {
    for (let i = 0; i < 7; i++) this.#noise({ start: i * 0.06, dur: 0.04, freq: 2200 + Math.random() * 1500, gain: 0.35 })
  }

  // A thud for a winning blow (a falling low note plus a puff of noise)
  hit() {
    this.#tone(150, { dur: 0.18, type: 'triangle', gain: 0.5, slideTo: 50 })
    this.#noise({ dur: 0.1, freq: 900, gain: 0.3 })
  }

  // A metallic clash for a tied pair of dice
  clash() {
    this.#noise({ dur: 0.12, freq: 3500, gain: 0.3 })
    this.#tone(520, { dur: 0.1, type: 'square', gain: 0.1 })
  }

  // Three rising notes when a country is conquered (or your turn starts)
  conquer() { [392, 523, 659].forEach((f, i) => this.#tone(f, { start: i * 0.12, dur: 0.3, type: 'triangle', gain: 0.35 })) }
  // A bright four-note rise for victory.
  victory() { [523, 659, 784, 1047].forEach((f, i) => this.#tone(f, { start: i * 0.16, dur: 0.6, type: 'triangle', gain: 0.4 })) }
  // A slow falling line for defeat.
  defeat() { [392, 330, 262, 196].forEach((f, i) => this.#tone(f, { start: i * 0.22, dur: 0.6, type: 'sawtooth', gain: 0.18 })) }

  // -------------------------------------------------------------- internals --------------------------------------------------

  // Remembers the volumes in the browser so they survive a refresh
  #save() { try { localStorage.setItem(KEY, JSON.stringify({ music: this.music, sfx: this.sfx })) } catch { /* ignore */ } }

  // Applies the current volumes and starts or stops the music timer as needed
  #apply() {
    if (!this.ctx) return
    // The music knob is halved because music is meant to sit quietly in the background
    this.musicGain.gain.value = this.music * 0.5
    this.sfxGain.gain.value = this.sfx
    if (this.music > 0 && !this.timer) {
      // Play the first bar now, then one more bar every 4 seconds
      this.#playBar()
      this.timer = setInterval(() => this.#playBar(), 4000)
    } else if (this.music === 0 && this.timer) {
      // Music turned all the way down: stop the timer.
      clearInterval(this.timer)
      this.timer = null
    }
  }

  // Plays the next 4-second bar of whichever track is selected
  #playBar() { this.track === 'game' ? this.#gameBar() : this.#menuBar() }

  // GAME track: a slow minor-key pad that cycles Am, F, C, G
  #gameBar() {
    const chords = [[110, 130.8, 164.8], [87.3, 130.8, 174.6], [130.8, 164.8, 196], [98, 123.5, 196]]
    const notes = chords[this.bar++ % chords.length]
    // Each chord note fades in slowly (attack 1.2s) and lasts just over the bar.
    notes.forEach((f) => this.#tone(f, { dur: 4.2, type: 'sine', gain: 0.35, attack: 1.2, dest: this.musicGain }))
  }

  // MENU track: a dreamy, harp-like arpeggio over a warm major pad, with a few high sparkles
  #menuBar() {
    // Four bright chords (Cmaj7, Am7, Fmaj7, G6). `pad` = low sustained notes, `arp` = notes to pluck
    const bars = [
      { pad: [130.81, 164.81, 196.0, 246.94], arp: [523.25, 659.25, 783.99, 987.77] },
      { pad: [110.0, 130.81, 164.81, 196.0], arp: [440.0, 523.25, 659.25, 783.99] },
      { pad: [87.31, 130.81, 174.61, 220.0], arp: [349.23, 440.0, 523.25, 659.25] },
      { pad: [98.0, 123.47, 146.83, 196.0], arp: [392.0, 493.88, 587.33, 783.99] }
    ]
    const bar = bars[this.bar++ % bars.length]
    // The warm pad: soft sine notes that swell in over a second
    bar.pad.forEach((f) => this.#tone(f, { dur: 4.2, type: 'sine', gain: 0.22, attack: 1.0, dest: this.musicGain }))
    // The plucked melody: eight notes, one every half second, going up and back down.
    const pattern = [0, 1, 2, 3, 2, 1, 2, 3]
    pattern.forEach((idx, i) => {
      this.#tone(bar.arp[idx], { start: i * 0.5, dur: 0.9, type: 'triangle', gain: 0.24, attack: 0.005, dest: this.musicGain })
    })
    // A couple of quiet high "sparkle" notes at random moments for a luxurious shimmer
    for (let i = 0; i < 2; i++) {
      this.#tone(bar.arp[Math.floor(Math.random() * 4)] * 2, {
        start: 0.25 + Math.random() * 3, dur: 1.2, type: 'sine', gain: 0.1, attack: 0.01, dest: this.musicGain
      })
    }
  }

  // Plays one musical note. `start` delays it, `dur` is its length, `attack` is the fade-in time,
  // `slideTo` makes the pitch glide, and `dest` chooses the volume knob it goes through
  #tone(freq, { start = 0, dur = 0.2, type = 'sine', gain = 0.3, attack = 0.01, slideTo = null, dest = null } = {}) {
    if (!this.ctx) return
    const t = this.ctx.currentTime + start                // when the note begins
    const osc = this.ctx.createOscillator()               // makes the raw wave
    const g = this.ctx.createGain()                       // shapes the loudness over time
    osc.type = type                                       // wave shape: sine is smooth, square is buzzy
    osc.frequency.setValueAtTime(freq, t)                 // the pitch
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(slideTo, t + dur)
    g.gain.setValueAtTime(0.0001, t)                      // start silent...
    g.gain.linearRampToValueAtTime(gain, t + attack)      // ...fade in...
    g.gain.linearRampToValueAtTime(0.0001, t + dur)       // ...then fade out
    osc.connect(g).connect(dest ?? this.sfxGain)          // wire it up to the speakers
    osc.start(t)
    osc.stop(t + dur + 0.05)                              // free the oscillator afterwards
  }

  // Plays a short burst of filtered noise (used for dice rattles and impacts)
  #noise({ start = 0, dur = 0.1, freq = 1500, gain = 0.3 } = {}) {
    if (!this.ctx) return
    const t = this.ctx.currentTime + start
    // Fill a small buffer with random numbers: that is "white noise".
    const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur))
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1
    const src = this.ctx.createBufferSource()
    const filter = this.ctx.createBiquadFilter()          // keeps only a band of frequencies
    const g = this.ctx.createGain()
    src.buffer = buffer
    filter.type = 'bandpass'
    filter.frequency.value = freq
    g.gain.setValueAtTime(gain, t)
    g.gain.linearRampToValueAtTime(0.0001, t + dur)
    src.connect(filter).connect(g).connect(this.sfxGain)
    src.start(t)
  }
}
